import { Link, useNavigate } from 'react-router-dom';

function Navbar({ isLoggedIn, setIsLoggedIn }) {
  const navigate = useNavigate();

  const handleProtectedNav = (path) => {
    if (!isLoggedIn) {
      alert('Please login or register to access this feature');
      navigate('/login');
    } else {
      navigate(path);
    }
  };

  const handleLogout = () => {
    const confirmLogout = window.confirm('Are you sure you want to logout?');
    if (confirmLogout) {
      setIsLoggedIn(false);
      navigate('/');
    }
  };

  return (
    <div className="navbar">

      {/* LEFT SIDE (LOGO / BRAND) */}
      <div className="logo">
        <Link to="/">Alumni Connect</Link>
      </div>

      {/* RIGHT SIDE (PILL NAVIGATION) */}
      <div className="nav-pills">
        <button onClick={() => navigate('/')}>Home</button>

        <button onClick={() => handleProtectedNav('/feed')}>
          Feed
        </button>

        <button onClick={() => handleProtectedNav('/events')}>
          Events
        </button>

        <button onClick={() => handleProtectedNav('/chat')}>
          Chat
        </button>

        {!isLoggedIn ? (
          <>
            <button onClick={() => navigate('/login')}>Login</button>
            <button onClick={() => navigate('/register')}>Register</button>
          </>
        ) : (
          <button onClick={handleLogout}>Logout</button>
        )}
      </div>

    </div>
  );
}

export default Navbar;
